"""Trading Intelligence Platform - Technical Signal Generator.

Produces discrete quantitative trade setups:
1. Trend Momentum (EMA Stack + ADX + RSI confirmation)
2. Mean Reversion (Bollinger Band extremity + RSI divergence / Pin Bar)
3. Volatility Squeeze Breakout (Bollinger Squeeze expansion + RVOL confirmation)
"""

from dataclasses import dataclass, field
from typing import Any

import pandas as pd

from models.base import SignalAction


@dataclass
class TechnicalSignal:
    """Discrete trade setup generated by technical analysis rules."""

    setup_name: str
    action: SignalAction
    strength: float  # 0.0 to 1.0
    horizon_bars: int = 5
    stop_loss_mult: float = 1.5  # Multiplier of ATR
    take_profit_mult: float = 3.0  # Multiplier of ATR
    reasons: list[str] = field(default_factory=list)
    metrics: dict[str, Any] = field(default_factory=dict)


class TechnicalSignalGenerator:
    """Evaluates engineered feature vectors to produce rule-based candidate trade setups."""

    def evaluate_bar(self, row: pd.Series) -> list[TechnicalSignal]:
        """Evaluate the latest bar row and return any triggered technical setups."""
        signals: list[TechnicalSignal] = []

        close = float(row.get("close", 0.0))
        atr = float(row.get("atr_14", close * 0.01))
        rsi = float(row.get("rsi_14", 50.0))
        adx = float(row.get("adx_14", 15.0))
        plus_di = float(row.get("plus_di_14", 20.0))
        minus_di = float(row.get("minus_di_14", 20.0))
        ema_bull_stack = int(row.get("ema_bullish_stack", 0))
        ema_bear_stack = int(row.get("ema_bearish_stack", 0))
        bb_pct_b = float(row.get("bb_pct_b_20", 0.5))
        rvol = float(row.get("rvol_20", 1.0))
        hammer = int(row.get("pattern_hammer", 0))
        shooting_star = int(row.get("pattern_shooting_star", 0))
        breakout = int(row.get("breakout_20", 0))
        breakdown = int(row.get("breakdown_20", 0))

        # 1. Trend Momentum Setup
        if ema_bull_stack == 1 and adx >= 25.0 and plus_di > minus_di and 45.0 <= rsi <= 68.0:
            signals.append(
                TechnicalSignal(
                    setup_name="TREND_MOMENTUM_BULL",
                    action=SignalAction.BUY,
                    strength=min(0.90, 0.60 + (adx / 100.0)),
                    horizon_bars=10,
                    stop_loss_mult=1.5,
                    take_profit_mult=3.0,
                    reasons=[
                        f"Bullish EMA stack alignment with strong ADX ({adx:.1f})",
                        f"RSI in positive momentum territory ({rsi:.1f})",
                    ],
                    metrics={"adx": adx, "rsi": rsi},
                )
            )
        elif ema_bear_stack == 1 and adx >= 25.0 and minus_di > plus_di and 32.0 <= rsi <= 55.0:
            signals.append(
                TechnicalSignal(
                    setup_name="TREND_MOMENTUM_BEAR",
                    action=SignalAction.SELL,
                    strength=min(0.90, 0.60 + (adx / 100.0)),
                    horizon_bars=10,
                    stop_loss_mult=1.5,
                    take_profit_mult=3.0,
                    reasons=[
                        f"Bearish EMA stack alignment with strong ADX ({adx:.1f})",
                        f"RSI in negative momentum territory ({rsi:.1f})",
                    ],
                    metrics={"adx": adx, "rsi": rsi},
                )
            )

        # 2. Mean Reversion Setup
        if rsi <= 30.0 and (bb_pct_b <= 0.05 or hammer == 1):
            signals.append(
                TechnicalSignal(
                    setup_name="MEAN_REVERSION_OVERSOLD",
                    action=SignalAction.BUY,
                    strength=0.75,
                    horizon_bars=5,
                    stop_loss_mult=1.0,
                    take_profit_mult=2.0,
                    reasons=[
                        f"Oversold RSI ({rsi:.1f}) at lower Bollinger Band limit (PctB: {bb_pct_b:.2f})",
                        "Exhaustion pin bar / hammer rejection confirmed" if hammer else "Band extremity reached",
                    ],
                    metrics={"rsi": rsi, "bb_pct_b": bb_pct_b},
                )
            )
        elif rsi >= 70.0 and (bb_pct_b >= 0.95 or shooting_star == 1):
            signals.append(
                TechnicalSignal(
                    setup_name="MEAN_REVERSION_OVERBOUGHT",
                    action=SignalAction.SELL,
                    strength=0.75,
                    horizon_bars=5,
                    stop_loss_mult=1.0,
                    take_profit_mult=2.0,
                    reasons=[
                        f"Overbought RSI ({rsi:.1f}) at upper Bollinger Band limit (PctB: {bb_pct_b:.2f})",
                        "Shooting star rejection confirmed" if shooting_star else "Band extremity reached",
                    ],
                    metrics={"rsi": rsi, "bb_pct_b": bb_pct_b},
                )
            )

        # 3. Volatility Breakout Setup
        if breakout == 1 and rvol >= 1.75:
            signals.append(
                TechnicalSignal(
                    setup_name="VOLATILITY_BREAKOUT_BULL",
                    action=SignalAction.BUY,
                    strength=0.80,
                    horizon_bars=8,
                    stop_loss_mult=1.2,
                    take_profit_mult=2.5,
                    reasons=[
                        "Resistance breakout with high relative volume expansion",
                        f"RVOL={rvol:.2f} confirms institutional participation",
                    ],
                    metrics={"rvol": rvol},
                )
            )
        elif breakdown == 1 and rvol >= 1.75:
            signals.append(
                TechnicalSignal(
                    setup_name="VOLATILITY_BREAKDOWN_BEAR",
                    action=SignalAction.SELL,
                    strength=0.80,
                    horizon_bars=8,
                    stop_loss_mult=1.2,
                    take_profit_mult=2.5,
                    reasons=[
                        "Support breakdown with high relative volume expansion",
                        f"RVOL={rvol:.2f} confirms institutional selling",
                    ],
                    metrics={"rvol": rvol},
                )
            )

        return signals
